```python
# Data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats
# End of data

# Import libraries
from cpmpy import *
import json

# Model
model = Model()

# Decision Variables
is_host = boolvar(shape=n_boats, name="is_host")  # 1 if boat is a host, 0 otherwise
visits = boolvar(shape=(n_boats, n_boats, n_periods), name="visits")  # visits[b1, b2, p] = 1 if boat b1 visits boat b2 in period p

# Constraints

# 1. A boat cannot visit itself
for b in range(n_boats):
    for p in range(n_periods):
        model += visits[b, b, p] == 0

# 2. A host boat stays host for all periods
for b in range(n_boats):
    for p in range(n_periods):
        model += is_host[b].implies(visits[b, b, p] == 0)  # Host doesn't visit itself
        for b2 in range(n_boats):
            if b2 != b:
                model += is_host[b].implies(visits[b, b2, p] == 0)  # Host doesn't visit others

# 3. Guest boats must visit exactly one host per period
for b in range(n_boats):
    for p in range(n_periods):
        if not is_host[b].value():  # Only for guest boats
            model += sum(visits[b, b2, p] for b2 in range(n_boats)) == 1

# 4. Capacity constraints
for b in range(n_boats):
    for p in range(n_periods):
        if is_host[b].value():
            total_people = crew_size[b] + sum(crew_size[b2] * visits[b2, b, p] for b2 in range(n_boats))
            model += total_people <= capacity[b]

# 5. No revisiting the same host
for b in range(n_boats):
    for b2 in range(n_boats):
        if b != b2:
            model += sum(visits[b, b2, p] for p in range(n_periods)) <= 1

# 6. Guest crews cannot meet more than once
for b1 in range(n_boats):
    for b2 in range(n_boats):
        if b1 != b2:
            for p1 in range(n_periods):
                for p2 in range(n_periods):
                    if p1 != p2:
                        # If b1 and b2 visit the same host in different periods, they meet
                        for h in range(n_boats):
                            if h != b1 and h != b2:
                                model += (visits[b1, h, p1] & visits[b2, h, p2]).implies(sum(visits[b1, h2, p2] for h2 in range(n_boats)) == 0)

# Objective: Minimize number of host boats
model.minimize(sum(is_host))

# Solve
if model.solve():
    solution = {
        "visits": [[[int(visits[b1, b2, p].value()) for p in range(n_periods)] for b2 in range(n_boats)] for b1 in range(n_boats)],
        "is_host": [int(h.value()) for h in is_host]
    }
    print(json.dumps(solution))
else:
    print("No solution found")
